/**
 * Catalog Data Reader for Static JSON Export
 * 
 * This module reads products and categories from a static JSON file
 * generated by the backend export functionality.
 * 
 * NOTE: This module is designed for BUILD TIME use only.
 * For client-side components, use the functions from index.ts which handle both
 * static JSON and fallback to hardcoded data.
 * 
 * The JSON file is generated at build time using:
 *   npm run import-products
 * 
 * This approach provides:
 * - Perfect SEO (static HTML pages)
 * - Fast loading (no API calls at runtime)
 * - Easy to update (just rebuild)
 */

// Type definitions for product data - these can be used everywhere
export interface ProductVariant {
  id: number;
  sku: string;
  title: string | null;
  price: number;
  mrp: number;
  cost_price: number | null;
  stock: number;
  weight_grams: number | null;
}

export interface ProductImage {
  id: number;
  url: string;
  path: string;
  is_primary: boolean;
  alt: string | null;
}

export interface ProductCategory {
  id: number;
  name: string;
  slug: string;
}

export interface Product {
  id: number;
  name: string;
  slug: string;
  description: string | null;
  seo_title: string | null;
  seo_description: string | null;
  brand: string | null;
  tags: string[];
  weight_grams: number | null;
  is_cod_allowed: boolean;
  hsn_code: string | null;
  gst_rate: number | null;
  category: ProductCategory | null;
  variants: ProductVariant[];
  images: ProductImage[];
  updated_at: string | null;
  created_at: string | null;
}

export interface Category {
  id: number;
  name: string;
  slug: string;
  description: string | null;
  parent_id: number | null;
  position: number | null;
  is_active: boolean;
}

export interface CatalogMeta {
  store_id?: number;
  store_name?: string;
  store_slug?: string;
  exported_at: string;
  product_count: number;
  category_count: number;
}

export interface CatalogData {
  products: Product[];
  categories: Category[];
  meta: CatalogMeta;
}

// Cache for performance during build
let cachedData: CatalogData | null = null;

/**
 * Get the path to the products JSON file
 * This is only used at build time on the server
 */
function getJsonPath(): string {
  // Try multiple possible locations
  // This function should only be called during build time
  const possiblePaths = [
    'public/products.json',
    '../public/products.json',
    'data/products.json',
    'products.json',
  ];

  // In Next.js, we can't use fs directly, so we return a relative path
  // The actual file reading should happen in build scripts
  return possiblePaths[0];
}

/**
 * THIS FUNCTION SHOULD ONLY BE CALLED DURING BUILD TIME (getStaticProps, etc.)
 * 
 * For client-side, use the getCatalogData from index.ts which handles both
 * static JSON and fallback to hardcoded data.
 */
export function getStaticCatalogData(): CatalogData | null {
  // This is a placeholder - actual implementation requires fs which doesn't work in browser
  // In practice, you should use getStaticProps or similar to read the JSON file
  
  // For now, return null to indicate JSON not available
  // The real data will be loaded via getStaticProps in page components
  return null;
}

/**
 * Reset the cached data (useful for testing)
 */
export function resetCache(): void {
  cachedData = null;
}

/**
 * Adapt static JSON product to old format for backward compatibility
 * This allows gradual migration from hardcoded to JSON data
 */
export function adaptProductToOldFormat(staticProduct: any): any {
  return {
    id: String(staticProduct.id),
    name: staticProduct.name,
    cat: staticProduct.category?.slug || 'other',
    desc: staticProduct.description || '',
    short: staticProduct.seo_description || staticProduct.description?.substring(0, 100) || '',
    price: staticProduct.variants?.[0]?.price || 0,
    mrp: staticProduct.variants?.[0]?.mrp || 0,
    rating: 4.5, // Default rating
    rev: Math.floor(Math.random() * 50) + 10, // Default reviews
    image: staticProduct.images?.[0]?.url || '/images/honey.webp',
    images: staticProduct.images?.map((img: any) => img.url) || [],
    opts: null,
    stock: staticProduct.variants?.[0]?.stock || 0,
    tags: staticProduct.tags || [],
    weight: staticProduct.weight_grams || 0,
    multi: null,
    d: staticProduct.seo_description || '',
  };
}

/**
 * Adapt static JSON category to old format
 */
export function adaptCategoryToOldFormat(staticCategory: any): any {
  return {
    slug: staticCategory.slug,
    name: staticCategory.name,
    blurb: staticCategory.description || '',
    image: '',
  };
}
